if [t['name'] for t in idx['types']] != tn: bad('types order')
cnt = np.bincount(types, minlength=len(tn))
if [t['count'] for t in idx['types']] != cnt.tolist(): bad('types count', cnt.tolist())
tmis = sum(1 for i in range(N) if ids[i].split('::')[0] != tn[types[i]])
print('type-by-prefix mismatches', tmis)
if tmis: bad('types.bin vs id prefix', tmis)
# ---- triples (cache) and independent degree
z = np.load(RAW + 'cache/triples.npz'); h, r, t = z['h'], z['r'], z['t']
print('triples', len(h))
if len(h) != idx['triples']: bad('triple count')
deg = np.bincount(h, minlength=N) + np.bincount(t, minlength=N)
if not np.array_equal(deg, degree.astype(np.int64)): bad('degree.bin != bincount')
rc = np.bincount(r, minlength=len(rels))
# ---- relations
gl = {}
lines = open(RAW + 'relation_glossary.tsv', encoding='utf-8').read().split('\n')
hdr = lines[0].split('\t')
for l in lines[1:]:
    if not l.strip(): continue
    c = dict(zip(hdr, l.split('\t'))); gl[c['Relation-name'].strip()] = c
if len(idx['relations']) != len(rels): bad('relation count')
tname = np.array(tn)
for i, rel in enumerate(idx['relations']):
    if rel['name'] != rels[i]: bad('rel name', i)
    if rel['count'] != rc[i]: bad('rel count', i, rel['count'], rc[i])
    hd, tl = rels[i].split(':')[-2:]
    if (rel['head'], rel['tail']) != (hd, tl): bad('rel head/tail', i, rel)
    m = r == i
    ht = set(np.unique(types[h[m]]).tolist()); tt = set(np.unique(types[t[m]]).tolist())
    if ht != {tn.index(hd)} or tt != {tn.index(tl)}: bad('rel types disagree', rels[i], [tn[x] for x in ht], [tn[x] for x in tt])
    g = gl.get(rels[i])
    if g is None: print('  no glossary row:', rels[i], '->', rel['label'], rel['source'])
    else:
