# ---- names
names = json.load(open(D + 'names.json', encoding='utf-8')); extra = json.load(open(G + 'names-extra.json', encoding='utf-8'))
ov = set(names) & set(extra)
print('names', len(names), 'extra', len(extra), 'overlap', len(ov))
if ov: bad('names overlap', len(ov))
if any(not (0 <= int(k) < N) for k in extra): bad('extra key range')
het = {}
for l in open(RAW + 'hetionet-v1.0-nodes.tsv', encoding='utf-8').read().split('\n')[1:]:
    p = l.split('\t')
    if len(p) >= 3: het[p[0]] = p[1]
# compare hetionet ids: try id as-is and with Gene:: etc
wrong = 0; unk = 0; ex = []
for k, v in extra.items():
    i = ids[int(k)]
    hv = het.get(i)
    if hv is None: unk += 1; ex.append((i, v)) if len(ex) < 5 else None
    elif hv != v: wrong += 1; print('  extra mismatch', i, repr(v), repr(hv)) if wrong < 5 else None
print('extra labels: hetionet-mismatch', wrong, 'not-in-hetionet', unk, ex[:5])
if wrong: bad('names-extra wrong labels', wrong)
from collections import Counter
print('extra by type', Counter(tn[types[int(k)]] for k in extra).most_common())
lab = set(map(int, names)) | set(map(int, extra))
print('unlabelled', N - len(lab))
# ---- shards: decode all headers, structure
files = sorted(f for f in os.listdir(G) if f.startswith('shard-'))
if len(files) != idx['shards'] or idx['shards'] != math.ceil(N / S): bad('shard count', len(files))
total = sum(os.path.getsize(G + f) for f in os.listdir(G))
print('graph/ bytes', total)
dec = {}
maxE = 0; nst = 0
for s in range(idx['shards']):
    b = open(G + 'shard-%03d.bin' % s, 'rb').read()
    hd = struct.unpack_from('<8I', b, 0)
    magic, first, rcnt, nE, nR, kk, z0, z1 = hd
    if magic != 0x314B4744 or first != s * S or rcnt != min(N, (s + 1) * S) - first or kk != K or z0 or z1: bad('header', s, hd)
