    eo = take(rcnt + 1); E = take(nE); ro = take(rcnt + 1); RC = take(nR); KR = take(rcnt * K); KD = take(rcnt * K, '<f4')
    if o != len(b): bad('size', s, o, len(b))
    if eo[0] != 0 or eo[-1] != nE or np.any(np.diff(eo.astype(np.int64)) < 0): bad('edgeOffsets', s)
    if ro[0] != 0 or ro[-1] != nR or np.any(np.diff(ro.astype(np.int64)) < 0): bad('relOffsets', s)
    if np.any(E >> 25): bad('edge high bits', s)
    if np.any((E & 0x1FFFF) >= N) or np.any(((E >> 17) & 0x7F) >= len(rels)): bad('edge range', s)
    if np.any(np.diff(eo.astype(np.int64)) > CAP): bad('cap exceeded', s)
    maxE = max(maxE, int(np.diff(eo.astype(np.int64)).max())); nst += nE
    # relCounts sums vs degree for every row
    sums = np.add.reduceat(np.append(RC & 0xFFFFFF, 0).astype(np.int64), ro[:-1].astype(np.int64)) if nR else None
    for i in range(rcnt):
        a, bb = ro[i], ro[i + 1]
        c = (RC[a:bb] & 0xFFFFFF).astype(np.int64)
        if c.sum() != degree[first + i]: bad('relCount sum', first + i, c.sum(), degree[first + i]); break
        if np.any(np.diff(c) > 0): bad('relCounts not desc', first + i); break
        if len(set((RC[a:bb] >> 24).tolist())) != bb - a: bad('relCounts dup rel', first + i); break
    kr = KR.reshape(rcnt, K); kd = KD.reshape(rcnt, K)
    rows = np.arange(first, first + rcnt)
    if np.any(kr == rows[:, None]): bad('knn self', s)
    if np.any(np.diff(kd, axis=1) < 0): bad('knn not asc', s)
    if np.any(types[kr] != types[rows][:, None]): bad('knn type', s, int((types[kr] != types[rows][:, None]).sum()))
    if np.any(kr >= N): bad('knn range', s)
    dec[s] = (first, eo.copy(), E.copy(), ro.copy(), RC.copy(), kr.copy(), kd.copy())
print('max edges/entity', maxE, 'stored', nst)
# ---- sample
rng = random.Random(7)
samp = set(rng.sample(range(N), 22))
for ty in ('Gene', 'Compound', 'Disease', 'Side Effect'):
    ti = tn.index(ty); m = np.where(types == ti)[0]; samp.add(int(m[np.argmax(degree[m])]))
leaves = np.where(degree == 1)[0]; samp.add(int(leaves[0])); samp.add(int(leaves[-1]))
samp.add(ent['Disease::MESH:D000690']); samp.add(ent['Gene::3480'])
loops = np.where(h == t)[0]
if len(loops): samp.add(int(h[loops[0]]))
samp = sorted(samp)
print('sample', len(samp), samp)
json.dump(samp, open(sys.argv[2] + '/samp.json', 'w'))
sset = np.zeros(N, bool); sset[samp] = True
m = sset[h] | sset[t]
hh, rr, tt = h[m], r[m], t[m]
src_pri = ['DRUGBANK', 'Hetionet', 'INTACT', 'STRING', 'DGIDB', 'bioarx', 'GNBR']
def pri(ri):
    p = rels[ri].split('::')[0]
    return (src_pri.index(p) if p in src_pri else len(src_pri), ri)
out = {}
for e in samp:
    s = e // S; first, eo, E, ro, RC, kr, kd = dec[s]; i = e - first
    ed = E[eo[i]:eo[i + 1]]
    nb = ed & 0x1FFFF; rl = (ed >> 17) & 0x7F; ou = (ed >> 24) & 1
    # true incidence set for e
    inc = set()
    mh = hh == e; mt = tt == e
    for a, b_, c in zip(hh[mh], rr[mh], tt[mh]): inc.add((int(c), int(b_), 1))
    for a, b_, c in zip(hh[mt], rr[mt], tt[mt]):
        if a != e: inc.add((int(a), int(b_), 0))
    stored = list(zip(nb.tolist(), rl.tolist(), ou.tolist()))
    if len(set(stored)) != len(stored): bad('dup stored edge', e)
    notreal = [x for x in stored if x not in inc]
    if notreal: bad('edge not a triple', e, ids[e], notreal[:3])
    if len(stored) != min(CAP, len(inc)): bad('edge count', e, len(stored), len(inc))
