// Mirrors the browser: fetch() -> ArrayBuffer -> the real graph-data.ts decoder.
import fs from 'node:fs'
import { pathToFileURL } from 'node:url'
const [, , ROOT, OUT] = process.argv
const PUB = ROOT + '/frontend/public'
globalThis.fetch = async (url) => {
  const p = PUB + url
  if (!fs.existsSync(p)) return { ok: false, status: 404 }
  const b = fs.readFileSync(p)
  const ab = b.buffer.slice(b.byteOffset, b.byteOffset + b.length)
  return { ok: true, status: 200, arrayBuffer: async () => ab, text: async () => b.toString('utf8'), json: async () => JSON.parse(b.toString('utf8')) }
}
const G = await import(pathToFileURL(ROOT + '/frontend/src/components/graph/graph-data.ts').href)
const fails = []
const bad = (...a) => { fails.push(a.join(' ')); console.log('FAIL', ...a) }
const index = await G.loadIndex()
const ids = await G.loadIds()
const extra = await G.loadNamesExtra()
console.log('index', !!index, 'ids', ids?.length, 'extra', Object.keys(extra).length)
if (ids.length !== 97238) bad('ids length', ids.length)
const py = JSON.parse(fs.readFileSync(OUT + '/py.json', 'utf8'))
const samp = JSON.parse(fs.readFileSync(OUT + '/samp.json', 'utf8'))
for (const row of samp) {
  const e = await G.loadEntity(row, index)
  const p = py[String(row)]
  const eq = (a, b) => a.length === b.length && a.every((x, i) => x === b[i])
  if (!eq(Array.from(e.edges), p.edges)) bad('edges', row)
  if (!eq(Array.from(e.relCounts), p.rc)) bad('relCounts', row)
  if (!eq(Array.from(e.knnRows), p.kr)) bad('knnRows', row)
  if (!eq(Array.from(e.knnDist), p.kd.map(Math.fround))) bad('knnDist', row)
  // helper decode vs py bit math
  for (const x of e.edges) {
    if (G.edgeNbr(x) !== (x & 0x1ffff) || G.edgeRel(x) !== ((x >>> 17) & 0x7f) || G.edgeOut(x) !== (((x >>> 24) & 1) === 1)) bad('helpers', row)
    if (G.edgeNbr(x) >= 97238 || G.edgeRel(x) >= index.relations.length) bad('range', row)
  }
  let sum = 0
  for (const x of e.relCounts) sum += G.relCount(x)
  if (row === 25880) {
    const names = JSON.parse(fs.readFileSync(PUB + '/drkg/names.json', 'utf8'))
    console.log('ALS', ids[row], 'relCount sum', sum, 'top', Array.from(e.relCounts.slice(0, 3), (x) => `${index.relations[G.relIdx(x)].label}=${G.relCount(x)}`).join(', '))
    console.log('  edges', Array.from(e.edges.slice(0, 4), (x) => `${G.edgeOut(x) ? '->' : '<-'} ${names[G.edgeNbr(x)] ?? ids[G.edgeNbr(x)]} [${index.relations[G.edgeRel(x)].name}]`).join(' | '))
  }
}
// every shard via the real decoder: offsets consistent and byte length exact
for (let s = 0; s < index.shards; s++) {
  const b = fs.readFileSync(`${PUB}/drkg/graph/shard-${String(s).padStart(3, '0')}.bin`)
  const ab = b.buffer.slice(b.byteOffset, b.byteOffset + b.length)
  const sh = G.decodeShard(ab)
  const end = sh.knnDist.byteOffset + sh.knnDist.byteLength
  if (end !== ab.byteLength) bad('decoded length', s, end, ab.byteLength)
  if (sh.firstRow !== s * index.shardSize) bad('firstRow', s)
  if (sh.edgeOffsets.at(-1) !== sh.edges.length || sh.relOffsets.at(-1) !== sh.relCounts.length) bad('offset tail', s)
}
// externalUrl
const ent = Object.fromEntries(ids.map((x, i) => [x, i]))
for (const id of ['Gene::3480', 'Compound::DB00945', 'Disease::MESH:D000690', 'Biological Process::GO:0055114', 'Gene::drugbank:BE0000048', 'Compound::CHEMBL1697690', 'Compound::MESH:C505380', 'Atc::M01AX18', 'Disease::DOID:0050156', 'Side Effect::C0027497', 'Gene::NVA101', 'Compound::brenda:226958', 'Tax::9606', 'Anatomy::UBERON:0000002', 'Symptom::D000006'])
  console.log('url', id, id in ent ? '' : '(not an id)', '->', G.externalUrl(id, index.externalUrl))
// prefixes in ids without a URL template
const pre = {}
for (const id of ids) { const u = G.externalUrl(id, index.externalUrl); const k = id.split('::')[0] + '::' + (id.split('::')[1].match(/^[A-Za-z_]+:?/)?.[0] ?? '<digits>'); pre[k] ??= [0, 0, u, id]; pre[k][u ? 0 : 1]++ }
console.log('prefix -> [withUrl, without, exampleUrl, exampleId]'); for (const [k, v] of Object.entries(pre).sort((a, b) => b[1][0] + b[1][1] - a[1][0] - a[1][1])) console.log(' ', k, JSON.stringify(v))
// search
const names = JSON.parse(fs.readFileSync(PUB + '/drkg/names.json', 'utf8'))
const types = new Uint8Array(fs.readFileSync(PUB + '/drkg/types.bin'))
const db = fs.readFileSync(PUB + '/drkg/degree.bin'); const degree = new Uint32Array(db.buffer.slice(db.byteOffset, db.byteOffset + db.length))
const si = G.buildSearch(97238, names, extra, ids)
let t0 = performance.now()
for (const q of ['riluzole', 'amyotrophic', 'IGF1R', 'D000690', 'DB00945', 'oxidation-reduction', 'nausea', 'GO:0055114', 'Gene::3480', 'als']) {
  const r = G.search(q, si, degree, types, new Set(), 5)
  console.log('search', JSON.stringify(q), '->', r.map((i) => `${si.label[i]} <${ids[i]}>`).join(' ; '))
}
console.log('10 searches ms', (performance.now() - t0).toFixed(1))
console.log('FAILS', fails.length)

