import sys, numpy as np
R = sys.argv[1]; RAW = R + '/data/raw/drkg/'
ent = {}
for l in open(RAW + 'embed/entities.tsv', encoding='utf-8'):
    a, b = l.rstrip('\n').split('\t'); ent[a] = int(b)
rel = {}
for l in open(RAW + 'embed/relations.tsv', encoding='utf-8'):
    a, b = l.rstrip('\n').split('\t'); rel[a] = int(b)
z = np.load(RAW + 'cache/triples.npz'); h, r, t = z['h'], z['r'], z['t']
n = 0; diff = 0
with open(RAW + 'drkg.tsv', encoding='utf-8') as f:
    for l in f:
        a, b, c = l.rstrip('\n').split('\t')
        if ent[a] != h[n] or rel[b] != r[n] or ent[c] != t[n]:
            diff += 1
            if diff < 4: print('diff at', n, a, b, c)
        n += 1
print('tsv lines', n, 'npz', len(h), 'mismatched rows', diff)

